CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE FUNCTION public.cleaning_admin(p_store uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.stores WHERE id=p_store AND slug='limpa-telhas-brusque') AND (public.is_platform_admin(auth.uid()) OR public.is_store_admin(auth.uid(),p_store)) $$;
REVOKE ALL ON FUNCTION public.cleaning_admin(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_admin(uuid) TO authenticated;
CREATE TABLE public.cleaning_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), product_id uuid NOT NULL REFERENCES public.products(id), kind text NOT NULL DEFAULT 'service' CHECK(kind IN ('service','addon')), mode text NOT NULL DEFAULT 'per_m2' CHECK(mode IN ('per_m2','fixed','percent')), price_ready boolean NOT NULL DEFAULT false, UNIQUE(product_id));
GRANT SELECT ON public.cleaning_catalog TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.cleaning_catalog TO authenticated; GRANT ALL ON public.cleaning_catalog TO service_role;
ALTER TABLE public.cleaning_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_catalog_read ON public.cleaning_catalog FOR SELECT USING (public.can_view_store_catalog(store_id));
CREATE POLICY cleaning_catalog_admin ON public.cleaning_catalog FOR ALL TO authenticated USING(public.cleaning_admin(store_id)) WITH CHECK(public.cleaning_admin(store_id));
CREATE TABLE public.cleaning_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), user_id uuid NOT NULL, customer_profile_id uuid NOT NULL REFERENCES public.customer_profiles(id), client_key uuid NOT NULL, number bigint GENERATED BY DEFAULT AS IDENTITY, customer jsonb NOT NULL, items jsonb NOT NULL DEFAULT '[]', addons jsonb NOT NULL DEFAULT '[]', details jsonb NOT NULL DEFAULT '{}', notes text NOT NULL DEFAULT '', total numeric(14,2), status text NOT NULL DEFAULT 'solicitado' CHECK(status IN ('solicitado','pronto','aceito','cancelado')), accepted_at timestamptz, order_id uuid REFERENCES public.orders(id), service_order_id uuid REFERENCES public.service_orders(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,user_id,client_key));
GRANT SELECT ON public.cleaning_quotes TO authenticated; GRANT ALL ON public.cleaning_quotes TO service_role;
ALTER TABLE public.cleaning_quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_quotes_read ON public.cleaning_quotes FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.cleaning_admin(store_id));
CREATE INDEX cleaning_quotes_store ON public.cleaning_quotes(store_id,created_at DESC);
CREATE TABLE public.cleaning_appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), quote_id uuid REFERENCES public.cleaning_quotes(id), user_id uuid NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'solicitado_agenda' CHECK(status IN ('solicitado_agenda','confirmado','em_andamento','concluido','cancelado','bloqueado')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT cleaning_positive_duration CHECK(ends_at>starts_at), CONSTRAINT cleaning_no_overlap EXCLUDE USING gist(store_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status IN ('confirmado','em_andamento','bloqueado')));
GRANT SELECT ON public.cleaning_appointments TO authenticated; GRANT ALL ON public.cleaning_appointments TO service_role;
ALTER TABLE public.cleaning_appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_appointments_read ON public.cleaning_appointments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.cleaning_admin(store_id));
CREATE UNIQUE INDEX cleaning_one_active_request ON public.cleaning_appointments(quote_id) WHERE status NOT IN ('cancelado','concluido') AND quote_id IS NOT NULL;
CREATE TABLE public.cleaning_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150), unit text NOT NULL DEFAULT 'un' CHECK(length(unit) BETWEEN 1 AND 10), quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK(quantity>=0), min_quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK(min_quantity>=0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cleaning_inventory TO authenticated; GRANT ALL ON public.cleaning_inventory TO service_role;
ALTER TABLE public.cleaning_inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_inventory_admin ON public.cleaning_inventory FOR ALL TO authenticated USING(public.cleaning_admin(store_id)) WITH CHECK(public.cleaning_admin(store_id));
CREATE TABLE public.cleaning_purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), inventory_id uuid NOT NULL REFERENCES public.cleaning_inventory(id), supplier text NOT NULL CHECK(length(trim(supplier)) BETWEEN 1 AND 200), quantity numeric(14,3) NOT NULL CHECK(quantity>0), total numeric(14,2) NOT NULL CHECK(total>0), due_date date NOT NULL, received_at timestamptz, client_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,client_key));
GRANT SELECT ON public.cleaning_purchases TO authenticated; GRANT ALL ON public.cleaning_purchases TO service_role;
ALTER TABLE public.cleaning_purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_purchases_admin ON public.cleaning_purchases FOR SELECT TO authenticated USING(public.cleaning_admin(store_id));
CREATE TABLE public.cleaning_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id), kind text NOT NULL CHECK(kind IN ('payable','receivable')), description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 250), party text NOT NULL DEFAULT '' CHECK(length(party)<=200), amount numeric(14,2) NOT NULL CHECK(amount>0), due_date date NOT NULL, paid_at timestamptz, payment_method text NOT NULL DEFAULT '' CHECK(length(payment_method)<=50), quote_id uuid REFERENCES public.cleaning_quotes(id), purchase_id uuid REFERENCES public.cleaning_purchases(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(quote_id), UNIQUE(purchase_id));
GRANT SELECT,INSERT,UPDATE ON public.cleaning_ledger TO authenticated; GRANT ALL ON public.cleaning_ledger TO service_role;
ALTER TABLE public.cleaning_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_ledger_admin ON public.cleaning_ledger FOR ALL TO authenticated USING(public.cleaning_admin(store_id)) WITH CHECK(public.cleaning_admin(store_id));
CREATE FUNCTION public.cleaning_catalog_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.products p JOIN public.stores s ON s.id=p.store_id WHERE p.id=NEW.product_id AND p.store_id=NEW.store_id AND s.slug='limpa-telhas-brusque') THEN RAISE EXCEPTION 'Produto de outra loja.'; END IF; IF NEW.kind='service' AND NEW.mode<>'per_m2' THEN RAISE EXCEPTION 'Serviços são cobrados por m².'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cleaning_catalog_guard BEFORE INSERT OR UPDATE ON public.cleaning_catalog FOR EACH ROW EXECUTE FUNCTION public.cleaning_catalog_guard();
CREATE FUNCTION public.cleaning_ledger_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NOT NULL AND NOT public.cleaning_admin(NEW.store_id) THEN RAISE EXCEPTION 'Sem permissão.'; END IF;
IF TG_OP='INSERT' AND auth.uid() IS NOT NULL AND (NEW.quote_id IS NOT NULL OR NEW.purchase_id IS NOT NULL) AND current_setting('mpz.cleaning_internal',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'Contas vinculadas são geradas pelo atendimento ou compra.'; END IF;
IF TG_OP='UPDATE' THEN IF NEW.store_id<>OLD.store_id OR NEW.kind<>OLD.kind OR NEW.quote_id IS DISTINCT FROM OLD.quote_id OR NEW.purchase_id IS DISTINCT FROM OLD.purchase_id THEN RAISE EXCEPTION 'Identidade da conta protegida.'; END IF;
IF OLD.paid_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Conta já paga; registro preservado.'; END IF;
IF (OLD.quote_id IS NOT NULL OR OLD.purchase_id IS NOT NULL) AND (NEW.amount<>OLD.amount OR NEW.description<>OLD.description OR NEW.party<>OLD.party) THEN RAISE EXCEPTION 'Valores vinculados protegidos.'; END IF;
END IF;
IF NEW.paid_at IS NOT NULL AND trim(NEW.payment_method)='' THEN RAISE EXCEPTION 'Informe a forma de pagamento.'; END IF;
IF NEW.quote_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cleaning_quotes WHERE id=NEW.quote_id AND store_id=NEW.store_id) THEN RAISE EXCEPTION 'Orçamento de outra loja.'; END IF;
IF NEW.purchase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.cleaning_purchases WHERE id=NEW.purchase_id AND store_id=NEW.store_id) THEN RAISE EXCEPTION 'Compra de outra loja.'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER cleaning_ledger_guard BEFORE INSERT OR UPDATE ON public.cleaning_ledger FOR EACH ROW EXECUTE FUNCTION public.cleaning_ledger_guard();
CREATE FUNCTION public.cleaning_paid_service() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.paid_at IS NOT NULL AND OLD.paid_at IS NULL AND NEW.quote_id IS NOT NULL AND NEW.kind='receivable' THEN UPDATE public.service_orders SET status='pago',paid_at=NEW.paid_at WHERE id=(SELECT service_order_id FROM public.cleaning_quotes WHERE id=NEW.quote_id AND store_id=NEW.store_id) AND store_id=NEW.store_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER cleaning_paid_service AFTER UPDATE ON public.cleaning_ledger FOR EACH ROW EXECUTE FUNCTION public.cleaning_paid_service();
CREATE FUNCTION public.cleaning_create_quote(p_store uuid,p_profile uuid,p_key uuid,p_input jsonb) RETURNS public.cleaning_quotes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE cp public.customer_profiles; q public.cleaning_quotes; e jsonb; c record; snapshot jsonb:='[]'; extras jsonb:='[]'; base numeric:=0; area_sum numeric:=0; area numeric; amount numeric; all_ready boolean:=true; customer_data jsonb; err text; seen uuid[]:='{}';
BEGIN
IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.stores WHERE id=p_store AND slug='limpa-telhas-brusque' AND is_active) THEN RAISE EXCEPTION 'Faça login nesta loja.'; END IF;
SELECT * INTO q FROM public.cleaning_quotes WHERE store_id=p_store AND user_id=auth.uid() AND client_key=p_key; IF FOUND THEN RETURN q; END IF;
SELECT * INTO cp FROM public.customer_profiles WHERE id=p_profile AND store_id=p_store AND is_active AND (user_id=auth.uid() OR public.cleaning_admin(p_store)); IF NOT FOUND THEN RAISE EXCEPTION 'Cadastro do cliente não autorizado.'; END IF;
customer_data:=jsonb_build_object('name',cp.name,'cpfCnpj',cp.cpf_cnpj,'whatsapp',cp.whatsapp,'cep',cp.cep,'uf',cp.uf,'city',cp.city,'neighborhood',cp.neighborhood,'address',cp.address,'number',cp.number,'complement',cp.complement);
err:=public.mpz_customer_error(customer_data); IF err IS NOT NULL THEN RAISE EXCEPTION '%',err; END IF;
IF jsonb_typeof(p_input->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'items') NOT BETWEEN 1 AND 3 OR jsonb_typeof(p_input->'addon_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'addon_ids')>30 OR length(coalesce(p_input->>'notes',''))>2000 OR (p_input->>'height')::numeric NOT BETWEEN 0 AND 100 OR p_input->>'access' NOT IN ('facil','restrito') OR jsonb_typeof(p_input->'water') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'electricity') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Dados do orçamento inválidos.'; END IF;
FOR e IN SELECT value FROM jsonb_array_elements(p_input->'items') LOOP
SELECT cc.*,p.name,p.base_price,p.code INTO c FROM public.cleaning_catalog cc JOIN public.products p ON p.id=cc.product_id AND p.store_id=cc.store_id WHERE cc.id=(e->>'service_id')::uuid AND cc.store_id=p_store AND cc.kind='service' AND p.is_active;
IF NOT FOUND OR c.id=ANY(seen) THEN RAISE EXCEPTION 'Serviço inválido.'; END IF; seen:=array_append(seen,c.id); area:=(e->>'area')::numeric; IF area IS NULL OR area<=0 OR area>100000 OR area::text IN ('NaN','Infinity') THEN RAISE EXCEPTION 'Área inválida.'; END IF;
IF c.base_price<0 THEN RAISE EXCEPTION 'Preço inválido.'; END IF;
all_ready:=all_ready AND c.price_ready; amount:=round(area*c.base_price,2); base:=base+amount; area_sum:=area_sum+area;
snapshot:=snapshot||jsonb_build_array(jsonb_build_object('service_id',c.id,'productId',c.product_id,'name',c.name,'code',c.code,'area',area,'quantity',area,'unit_price',CASE WHEN c.price_ready THEN c.base_price ELSE NULL END,'price',c.base_price,'total',CASE WHEN c.price_ready THEN amount ELSE NULL END));
END LOOP;
FOR e IN SELECT value FROM jsonb_array_elements(p_input->'addon_ids') LOOP
SELECT cc.*,p.name,p.base_price,p.code INTO c FROM public.cleaning_catalog cc JOIN public.products p ON p.id=cc.product_id AND p.store_id=cc.store_id WHERE cc.id=(e#>>'{}')::uuid AND cc.store_id=p_store AND cc.kind='addon' AND p.is_active;
IF NOT FOUND OR c.id=ANY(seen) OR c.base_price<0 THEN RAISE EXCEPTION 'Adicional inválido.'; END IF; seen:=array_append(seen,c.id); all_ready:=all_ready AND c.price_ready;
amount:=round(c.base_price*(CASE c.mode WHEN 'per_m2' THEN area_sum WHEN 'percent' THEN base/100 ELSE 1 END),2);
extras:=extras||jsonb_build_array(jsonb_build_object('service_id',c.id,'productId',c.product_id,'name',c.name,'code',c.code,'mode',c.mode,'unit_price',CASE WHEN c.price_ready THEN c.base_price ELSE NULL END,'total',CASE WHEN c.price_ready THEN amount ELSE NULL END));
END LOOP;
amount:=base+coalesce((SELECT sum((v->>'total')::numeric) FROM jsonb_array_elements(extras) v),0);
IF all_ready AND amount<=0 THEN RAISE EXCEPTION 'Cadastre um preço maior que zero.'; END IF;
INSERT INTO public.cleaning_quotes(store_id,user_id,customer_profile_id,client_key,customer,items,addons,details,notes,total,status) VALUES(p_store,coalesce(cp.user_id,auth.uid()),p_profile,p_key,customer_data,snapshot,extras,p_input-'items'-'addon_ids'-'notes',coalesce(p_input->>'notes',''),CASE WHEN all_ready THEN amount ELSE NULL END,CASE WHEN all_ready THEN 'pronto' ELSE 'solicitado' END) RETURNING * INTO q;
RETURN q;
END $$;
REVOKE ALL ON FUNCTION public.cleaning_create_quote(uuid,uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_create_quote(uuid,uuid,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.cleaning_review_quote(p_id uuid,p_total numeric) RETURNS public.cleaning_quotes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.cleaning_quotes; BEGIN SELECT * INTO q FROM public.cleaning_quotes WHERE id=p_id FOR UPDATE; IF NOT FOUND OR NOT public.cleaning_admin(q.store_id) THEN RAISE EXCEPTION 'Sem permissão.'; END IF; IF q.status NOT IN ('solicitado','pronto') OR p_total IS NULL OR p_total<=0 OR p_total>999999999 THEN RAISE EXCEPTION 'Orçamento ou valor inválido.'; END IF; UPDATE public.cleaning_quotes SET total=round(p_total,2),status='pronto' WHERE id=p_id RETURNING * INTO q; RETURN q; END $$;
REVOKE ALL ON FUNCTION public.cleaning_review_quote(uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_review_quote(uuid,numeric) TO authenticated;
CREATE FUNCTION public.cleaning_accept_quote(p_id uuid,p_expected_total numeric) RETURNS public.cleaning_quotes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q public.cleaning_quotes; o public.orders; so public.service_orders; order_items jsonb; BEGIN
SELECT * INTO q FROM public.cleaning_quotes WHERE id=p_id FOR UPDATE;
IF NOT FOUND OR auth.uid() IS NULL OR (q.user_id<>auth.uid() AND NOT public.cleaning_admin(q.store_id)) THEN RAISE EXCEPTION 'Sem permissão.'; END IF;
IF q.status='aceito' THEN RETURN q; END IF;
IF q.status<>'pronto' OR q.total IS NULL OR q.total IS DISTINCT FROM p_expected_total THEN RAISE EXCEPTION 'Orçamento mudou ou ainda aguarda preço. Atualize antes de aceitar.'; END IF;
order_items:=q.items;
INSERT INTO public.orders(store_id,user_id,customer,items,subtotal,discount,delivery_fee,total,status,payment_method,delivery_shift,observations) VALUES(q.store_id,q.user_id,q.customer,order_items,q.total,0,0,q.total,'orcamento','a_combinar','',q.notes) RETURNING * INTO o;
INSERT INTO public.service_orders(store_id,order_id,user_id,os_number,customer,items,extra_items,subtotal,discount,total,status,observations) VALUES(q.store_id,o.id,q.user_id,o.order_number,q.customer,order_items,'[]',q.total,0,q.total,'aberta',q.notes) RETURNING * INTO so;
UPDATE public.cleaning_quotes SET status='aceito',accepted_at=now(),order_id=o.id,service_order_id=so.id WHERE id=p_id RETURNING * INTO q;
PERFORM set_config('mpz.cleaning_internal','yes',true);
INSERT INTO public.cleaning_ledger(store_id,kind,description,party,amount,due_date,quote_id) VALUES(q.store_id,'receivable','Orçamento #'||q.number,q.customer->>'name',q.total,(now() AT TIME ZONE 'America/Sao_Paulo')::date,q.id);
RETURN q;
END $$;
REVOKE ALL ON FUNCTION public.cleaning_accept_quote(uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_accept_quote(uuid,numeric) TO authenticated;
CREATE FUNCTION public.cleaning_busy(p_store uuid,p_from timestamptz,p_to timestamptz) RETURNS TABLE(starts_at timestamptz,ends_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.starts_at,a.ends_at FROM public.cleaning_appointments a JOIN public.stores s ON s.id=a.store_id WHERE s.id=p_store AND s.slug='limpa-telhas-brusque' AND s.is_active AND a.status IN ('confirmado','em_andamento','bloqueado') AND a.starts_at<p_to AND a.ends_at>p_from AND p_to-p_from<=interval '40 days' $$;
REVOKE ALL ON FUNCTION public.cleaning_busy(uuid,timestamptz,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_busy(uuid,timestamptz,timestamptz) TO anon,authenticated;
CREATE FUNCTION public.cleaning_schedule(p_store uuid,p_quote uuid,p_start timestamptz,p_end timestamptz,p_notes text DEFAULT '') RETURNS public.cleaning_appointments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q public.cleaning_quotes; a public.cleaning_appointments; BEGIN
IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.stores WHERE id=p_store AND slug='limpa-telhas-brusque' AND is_active) THEN RAISE EXCEPTION 'Faça login.'; END IF;
IF p_start IS NULL OR p_end IS NULL OR p_start<=now() OR p_end<=p_start OR p_end-p_start>interval '24 hours' OR length(p_notes)>2000 THEN RAISE EXCEPTION 'Informe data e duração válidas, no futuro.'; END IF;
IF p_quote IS NULL THEN IF NOT public.cleaning_admin(p_store) THEN RAISE EXCEPTION 'Sem permissão para bloquear agenda.'; END IF;
INSERT INTO public.cleaning_appointments(store_id,user_id,starts_at,ends_at,status,notes) VALUES(p_store,auth.uid(),p_start,p_end,'bloqueado',p_notes) RETURNING * INTO a; RETURN a; END IF;
SELECT * INTO q FROM public.cleaning_quotes WHERE id=p_quote AND store_id=p_store FOR UPDATE;
IF NOT FOUND OR q.status<>'aceito' OR (q.user_id<>auth.uid() AND NOT public.cleaning_admin(p_store)) THEN RAISE EXCEPTION 'Aceite um orçamento autorizado antes de agendar.'; END IF;
IF EXISTS(SELECT 1 FROM public.cleaning_appointments WHERE store_id=p_store AND status IN ('confirmado','em_andamento','bloqueado') AND starts_at<p_end AND ends_at>p_start) THEN RAISE EXCEPTION 'Horário indisponível.'; END IF;
SELECT * INTO a FROM public.cleaning_appointments WHERE quote_id=p_quote AND status NOT IN ('cancelado','concluido') FOR UPDATE;
IF FOUND THEN IF a.status<>'solicitado_agenda' THEN RAISE EXCEPTION 'Contate a loja para alterar um horário confirmado.'; END IF; UPDATE public.cleaning_appointments SET starts_at=p_start,ends_at=p_end,notes=p_notes WHERE id=a.id RETURNING * INTO a;
ELSE INSERT INTO public.cleaning_appointments(store_id,quote_id,user_id,starts_at,ends_at,notes) VALUES(p_store,p_quote,q.user_id,p_start,p_end,p_notes) RETURNING * INTO a; END IF;
RETURN a; END $$;
REVOKE ALL ON FUNCTION public.cleaning_schedule(uuid,uuid,timestamptz,timestamptz,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_schedule(uuid,uuid,timestamptz,timestamptz,text) TO authenticated;
CREATE FUNCTION public.cleaning_appointment_action(p_id uuid,p_status text,p_start timestamptz DEFAULT NULL,p_end timestamptz DEFAULT NULL) RETURNS public.cleaning_appointments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.cleaning_appointments; BEGIN
SELECT * INTO a FROM public.cleaning_appointments WHERE id=p_id FOR UPDATE;
IF NOT FOUND OR auth.uid() IS NULL OR NOT public.cleaning_admin(a.store_id) THEN RAISE EXCEPTION 'Sem permissão.'; END IF;
IF p_status NOT IN ('confirmado','em_andamento','concluido','cancelado') OR a.status IN ('cancelado','concluido') OR (a.status='bloqueado' AND p_status<>'cancelado') OR (p_status='em_andamento' AND a.status<>'confirmado') OR (p_status='concluido' AND a.status NOT IN ('confirmado','em_andamento')) THEN RAISE EXCEPTION 'Transição de atendimento inválida.'; END IF;
IF p_start IS NOT NULL AND (p_end IS NULL OR p_end<=p_start OR p_end-p_start>interval '24 hours' OR p_start<=now()) THEN RAISE EXCEPTION 'Data inválida.'; END IF;
UPDATE public.cleaning_appointments SET status=p_status,starts_at=coalesce(p_start,starts_at),ends_at=coalesce(p_end,ends_at) WHERE id=p_id RETURNING * INTO a;
IF p_status IN ('em_andamento','concluido') THEN UPDATE public.service_orders SET status=CASE WHEN p_status='concluido' THEN 'concluida' ELSE 'em_andamento' END WHERE id=(SELECT service_order_id FROM public.cleaning_quotes WHERE id=a.quote_id AND store_id=a.store_id) AND status<>'pago'; END IF;
RETURN a; END $$;
REVOKE ALL ON FUNCTION public.cleaning_appointment_action(uuid,text,timestamptz,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_appointment_action(uuid,text,timestamptz,timestamptz) TO authenticated;
CREATE FUNCTION public.cleaning_purchase(p_store uuid,p_inventory uuid,p_supplier text,p_quantity numeric,p_total numeric,p_due date,p_key uuid) RETURNS public.cleaning_purchases LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.cleaning_purchases; BEGIN
IF NOT public.cleaning_admin(p_store) OR NOT EXISTS(SELECT 1 FROM public.cleaning_inventory WHERE id=p_inventory AND store_id=p_store) THEN RAISE EXCEPTION 'Sem permissão ou item de outra loja.'; END IF;
SELECT * INTO p FROM public.cleaning_purchases WHERE store_id=p_store AND client_key=p_key; IF FOUND THEN RETURN p; END IF;
IF p_quantity IS NULL OR p_quantity<=0 OR p_total IS NULL OR p_total<=0 OR p_due IS NULL OR length(trim(p_supplier)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Dados da compra inválidos.'; END IF;
INSERT INTO public.cleaning_purchases(store_id,inventory_id,supplier,quantity,total,due_date,client_key) VALUES(p_store,p_inventory,p_supplier,p_quantity,p_total,p_due,p_key) RETURNING * INTO p;
PERFORM set_config('mpz.cleaning_internal','yes',true);
INSERT INTO public.cleaning_ledger(store_id,kind,description,party,amount,due_date,purchase_id) VALUES(p_store,'payable','Compra — '||(SELECT name FROM public.cleaning_inventory WHERE id=p_inventory),p_supplier,p_total,p_due,p.id); RETURN p; END $$;
REVOKE ALL ON FUNCTION public.cleaning_purchase(uuid,uuid,text,numeric,numeric,date,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_purchase(uuid,uuid,text,numeric,numeric,date,uuid) TO authenticated;
CREATE FUNCTION public.cleaning_receive_purchase(p_id uuid) RETURNS public.cleaning_purchases LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.cleaning_purchases; BEGIN SELECT * INTO p FROM public.cleaning_purchases WHERE id=p_id FOR UPDATE; IF NOT FOUND OR NOT public.cleaning_admin(p.store_id) THEN RAISE EXCEPTION 'Sem permissão.'; END IF; IF p.received_at IS NOT NULL THEN RETURN p; END IF;
UPDATE public.cleaning_inventory SET quantity=quantity+p.quantity WHERE id=p.inventory_id AND store_id=p.store_id;
UPDATE public.cleaning_purchases SET received_at=now() WHERE id=p_id RETURNING * INTO p; RETURN p; END $$;
REVOKE ALL ON FUNCTION public.cleaning_receive_purchase(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_receive_purchase(uuid) TO authenticated;
CREATE FUNCTION public.cleaning_save_catalog(p_store uuid,p_id uuid,p_name text,p_price numeric,p_ready boolean,p_kind text,p_mode text,p_image text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.cleaning_catalog; pid uuid; BEGIN
IF NOT public.cleaning_admin(p_store) OR length(trim(p_name)) NOT BETWEEN 1 AND 200 OR p_price IS NULL OR p_price<0 OR p_price>999999999 OR (p_ready AND p_price<=0) OR p_kind NOT IN ('service','addon') OR p_mode NOT IN ('per_m2','fixed','percent') OR (p_kind='service' AND p_mode<>'per_m2') OR length(p_image)>2000 THEN RAISE EXCEPTION 'Dados do produto inválidos.'; END IF;
IF p_id IS NULL THEN INSERT INTO public.products(store_id,name,base_price,unit,code,image_url) VALUES(p_store,trim(p_name),p_price,CASE WHEN p_mode='per_m2' THEN 'm²' ELSE 'un' END,'LT-'||substr(gen_random_uuid()::text,1,8),p_image) RETURNING id INTO pid;
INSERT INTO public.cleaning_catalog(store_id,product_id,kind,mode,price_ready) VALUES(p_store,pid,p_kind,p_mode,p_ready) RETURNING * INTO c;
ELSE SELECT * INTO c FROM public.cleaning_catalog WHERE id=p_id AND store_id=p_store FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Produto não autorizado.'; END IF;
UPDATE public.products SET name=trim(p_name),base_price=p_price,image_url=p_image WHERE id=c.product_id AND store_id=p_store;
UPDATE public.cleaning_catalog SET mode=p_mode,kind=p_kind,price_ready=p_ready WHERE id=c.id; END IF; RETURN c.id; END $$;
REVOKE ALL ON FUNCTION public.cleaning_save_catalog(uuid,uuid,text,numeric,boolean,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cleaning_save_catalog(uuid,uuid,text,numeric,boolean,text,text,text) TO authenticated;